import{c as e,o as t,b as a}from"./index-D22dK0d7.js";const o={class:"markdown-body"},c={__name:"Массовые рассылки из CRM",setup(r,{expose:B}){return B({frontmatter:{}}),(s,D)=>(t(),e("div",o,[...D[0]||(D[0]=[a('<p>При использовании сервиса для отправки массовой рассылки из сторонних CRM-систем по клиентской базе вероятность блокировки со стороны WhatsApp* и/или Telegram значительно выше — из-за специфики отправки сообщений из CRM (как правило, сообщения отправляются одномоментно).</p><blockquote><p>Одномоментная отправка большого числа одинаковых сообщений — один из главных признаков спама для мессенджеров, даже если аккаунт был заранее «прогрет» (см. <a href="%D0%9F%D1%80%D0%BE%D0%B3%D1%80%D0%B5%D0%B2%20%D0%B0%D0%BA%D0%BA%D0%B0%D1%83%D0%BD%D1%82%D0%BE%D0%B2%20%D0%B8%20%D0%B1%D0%BB%D0%BE%D0%BA%D0%B8%D1%80%D0%BE%D0%B2%D0%BA%D0%B0%20WhatsApp,%20Telegram.md">Прогрев аккаунтов и блокировка WhatsApp, Telegram</a>).</p></blockquote><p>Для создания массовых рассылок по клиентской базе рекомендуется подключить отдельную функцию массовых рассылок — она предназначена для плавных интервальных рассылок вместо одномоментной отправки из CRM. Настройка параметров рассылки осуществляется через интерфейс личного кабинета, в разделе <a href="/Accounts">«Группы»</a> (см. <a href="%D0%93%D1%80%D1%83%D0%BF%D0%BF%D1%8B%3A%20%D0%9A%D0%B0%D1%81%D0%BA%D0%B0%D0%B4%D0%BD%D0%B0%D1%8F%20%D1%80%D0%B0%D1%81%D1%81%D1%8B%D0%BB%D0%BA%D0%B0%20%D1%81%D0%BE%D0%BE%D0%B1%D1%89%D0%B5%D0%BD%D0%B8%D0%B9.md">Группы: Каскадная рассылка сообщений</a>).</p><hr><p><em>* Принадлежит компании Meta, которая признана экстремистской организацией и запрещена на территории РФ.</em></p>',5)])]))}};export{c as default};
